// ========== PE 头检查绕过 (擦除 DOS header MZ) ==========
void wipe_headers(unsigned char *base, size_t size) {
    // 擦除 DOS header + NT headers + section headers
    PIMAGE_DOS_HEADER dos = (PIMAGE_DOS_HEADER)base;
    if (dos->e_magic != 0x5A4D) return; // 不是标准PE
    DWORD headerSize = dos->e_lfanew;
    // 覆盖头部为零
    ZeroMemory(base, headerSize);
}

